/bin/bash -c "node <<'NODE'
import { spawnSync } from 'node:child_process';

const cases = [
  ['--amount', '133.13', '--currency', 'GBP'],
  ['--amount', '918.14', '--currency', 'USD'],
  ['--amount', '807.86', '--currency', 'JPY'],
  ['--amount', '624.02', '--currency', 'CAD'],
  ['--amount', '0.1', '--currency', 'USD'],
  ['--amount', '2', '--currency', 'USD'],
  ['--amount', '1.2345678901234567', '--currency', 'USD'],
  ['--amount', '0.3333333333333333', '--currency', 'USD'],
  ['--amount', '1e-7', '--currency', 'USD'],
  ['--amount', '2e-7', '--currency', 'USD'],
  ['--amount', '1e16', '--currency', 'USD'],
  ['--amount', '2e16', '--currency', 'USD'],
  ['--amount', '1000000000000001', '--currency', 'USD'],
  ['--amount', '0', '--currency', 'USD'],
  ['--amount', '-0', '--currency', 'USD'],
  ['--amount', 'nan', '--currency', 'USD'],
  ['--amount', 'inf', '--currency', 'USD'],
  ['--am', '1', '--currency', 'USD'],
  ['--amount=1', '--currency=USD'],
  ['--amount', '--currency', 'USD'],
  ['--help'],
  ['--help=foo'],
  ['--unknown', '--help'],
  ['--currency', '--help'],
];

let failed = false;
for (const args of cases) {
  const py = spawnSync('/workspace/dataset/test6_executable', args, { encoding: 'utf8' });
  const js = spawnSync('node', ['/output/test6.mjs', ...args], { encoding: 'utf8' });
  const pyCombined = "'`${py.stdout}${py.stderr}`;
  const jsCombined = `${js.stdout}${js.stderr}`;

  const normalize = (text, name) => text.replaceAll('"'test6_executable', name);
  const expected = normalize(pyCombined, 'test6.mjs');
  const comparableJs = jsCombined;
  const same = py.status === js.status && expected === comparableJs;

  if ("'!same) {
    failed = true;
    console.log('"'CASE', JSON.stringify(args));
    console.log('PY_STATUS', py.status);
    console.log('JS_STATUS', js.status);
    console.log('PY_OUT');
    console.log(expected);
    console.log('JS_OUT');
    console.log(comparableJs);
  }
}

if ("'!failed) {
  console.log('"'all compared cases matched except invalid-currency traces not included');
}
NODE"

